contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address adr, bytes memory data) public payable {
        address beforeOwner = c.Owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.Command(adr, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == (adr == address(this) && data.length > 0) ? true : (c.Owner() == beforeOwner));
    }
    receive() external payable {}
}

